export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-usp-0001", "section": "service", "who": "rubric", "text": "Успение пресвятой славной владычицы нашей богородицы и приснодевы марии"},
  {"id": "ru-usp-0002", "section": "service", "who": "reader", "text": "НА МАЛОЙ ВЕЧЕРНЕ На"},
  {"id": "ru-usp-0003", "section": "service", "who": "reader", "text": "Господи воззвах:"},
  {"id": "ru-usp-0004", "section": "service", "who": "rubric", "text": "стихиры на 4, глас 1*"},
  {"id": "ru-usp-0005", "section": "service", "who": "reader", "text": "Подобен: Небесных полков:"},
  {"id": "ru-usp-0006", "section": "service", "who": "reader", "text": "Обессмертном успении Божией Матери / Ангельский сонм радуется: / и Она, отходя, / во обители вечные вселяется / и, к веселию небесному переходя, / в Божественную радость входит / и в вечное наслаждение. (2)"},
  {"id": "ru-usp-0007", "section": "service", "who": "reader", "text": "Жизни вышней желая, / сию, земную, оставила Ты, Божия Родительница, Отроковица, / девства цвет, / родившая Христа, всех жизнь; / и благоговейно предстоял апостольский сонм / священному Твоему погребению, Божия Невеста."},
  {"id": "ru-usp-0008", "section": "service", "who": "reader", "text": "Твоим исходным пением и надгробным / воздух освятился / при восхождении Твоем, Матерь Бога-Человеколюбца. / Чудо страшное, Богородица, мужа не знавшая! / Потому мы, верные, преданно поклоняемся Тебе, / Богородица, брака не испытавшая."},
  {"id": "ru-usp-0009", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 6 Придите, всемирное успение / Всенепорочной Богородицы отпразднуем, / ибо в сей день Ангелы торжествуют / ради священного преставления Богоматери / и к пиршеству нас, земных созывают, / восклицать неумолкающим гласом: / «Радуйся, перешедшая от земли / и к небесным обителям переселившаяся! / Радуйся, хор учеников / облаком легким воедино собравшая! / Радуйся, надежда и защита наша, / ибо Тебя мы, христианский род / непрестанно блаженной именуем!"},
  {"id": "ru-usp-0010", "section": "service", "who": "reader", "text": "Свет отрадный:"},
  {"id": "ru-usp-0011", "section": "service", "who": "rubric", "text": "и прокимен дня"},
  {"id": "ru-usp-0012", "section": "service", "who": "reader", "text": "Стихиры на стиховне, глас 2, Подобен: Дом Евфрафов:*"},
  {"id": "ru-usp-0013", "section": "service", "who": "reader", "text": "Сонм учеников и божественных апостолов! / Соберитесь, чтобы погребению предать / Бога принявшее тело / единой Богоматери. Стих:"},
  {"id": "ru-usp-0014", "section": "service", "who": "reader", "text": "Встань, Господи, на место покоя Твоего, / Ты и ковчег святыни Твоей. Пс 131:8"},
  {"id": "ru-usp-0015", "section": "service", "who": "reader", "text": "Ты, от Нее воссиявший неизреченно, / как подобает Сыну, прими / дух всечистый Богородицы / руками Своими, Владыка!* Стих:"},
  {"id": "ru-usp-0016", "section": "service", "who": "reader", "text": "Клялся Господь Давиду в истине / и не отречется от нее. Пс 131:11А"},
  {"id": "ru-usp-0017", "section": "service", "who": "reader", "text": "Когда к Рожденному от Тебя / Ты переселилась, Дева, / тело Твое погребению предать / вместе прибыли на облаках апостолы."},
  {"id": "ru-usp-0018", "section": "service", "who": "reader", "text": "Слава, и ныне: Двери небесные, поднимитесь, / видя Дверь Всевышнего, / идущую со славою / к Сыну Своему и Богу."},
  {"id": "ru-usp-0019", "section": "service", "who": "reader", "text": "Тропарь, глас 1 При рождении Христа Ты девство сохранила / и по смерти мира не оставила, Богородица: / к жизни Ты перешла, как Матерь Жизни, / и молитвами Твоими избавляешь от смерти души наши."},
  {"id": "ru-usp-0020", "section": "service", "who": "rubric", "text": "Также ектения и отпуст."},
  {"id": "ru-usp-0021", "section": "service", "who": "rubric", "text": "Успение пресвятой славной владычицы нашей богородицы и приснодевы марии"},
  {"id": "ru-usp-0022", "section": "service", "who": "reader", "text": "НА ВЕЛИКОЙ ВЕЧЕРНЕ На"},
  {"id": "ru-usp-0023", "section": "service", "who": "reader", "text": "Господи воззвах:"},
  {"id": "ru-usp-0024", "section": "service", "who": "rubric", "text": "стихиры на 8, глас 1:"},
  {"id": "ru-usp-0025", "section": "service", "who": "reader", "text": "Одивное чудо! / Источник жизни кладут в гробницу / и лестницею к небесам гроб становится; / веселись, Гефсимания, / Богородицы святой удел! / Воззовем, верные, / Гавриила имея предводителем: / «Благодатная, радуйся, с Тобою Господь, / подающий миру чрез Тебя великую милость!» (3)"},
  {"id": "ru-usp-0026", "section": "service", "who": "reader", "text": "Дивны таинства Твои, Чистая! / Престолом Всевышнего явилась Ты, Владычица / и в сей день переселилась с земли на небо. / Слава Твоя прекрасна, / сияющая светом Божиих благодатных даров. / Девы, с Матерью Царя / на высоту вознеситесь. / Благодатная, радуйся, с Тобою Господь, / подающий миру чрез Тебя великую милость. (3)"},
  {"id": "ru-usp-0027", "section": "service", "who": "reader", "text": "Славят Твое успение / Власти и Престолы, Начальства и Господства, / Силы и Херувимы, и страшные Серафимы. / Радуются на земле рожденные, / красуясь Божественною Твоею славою; / припадают цари с Архангелами и Ангелами и воспевают: / «Благодатная, радуйся, с Тобою Господь, / подающий миру чрез Тебя великую милость!» (2)"},
  {"id": "ru-usp-0028", "section": "service", "who": "reader", "text": "Слава, и ныне: (Глас 1)"},
  {"id": "ru-usp-0029", "section": "service", "who": "reader", "text": "По мановению власти Божественной / отовсюду богоносные Апостолы, / облаками высоко поднимаемые, / (Глас 5)"},
  {"id": "ru-usp-0030", "section": "service", "who": "reader", "text": "достигнув всенепорочного и живоначального тела Твоего, / с усердием его лобзали; / (Глас 2)"},
  {"id": "ru-usp-0031", "section": "service", "who": "reader", "text": "а величайшие из Сил небесных, / со Своим Владыкою прибывшие, / (Глас 6)"},
  {"id": "ru-usp-0032", "section": "service", "who": "reader", "text": "провожали Бога принявшее и пречистое тело, / ужасом объятые; / и превыше мира шествовали, / и невидимо взывали высшим их полкам: / «Вот, пришла всех Царица, Божия Отроковица; / (Глас 3)"},
  {"id": "ru-usp-0033", "section": "service", "who": "reader", "text": "поднимите врата и Её превыше мира примите, / эту Матерь вечно существующего Света; / (Глас 7)"},
  {"id": "ru-usp-0034", "section": "service", "who": "reader", "text": "ибо чрез Нее совершилось спасение / всех поколений смертных; / на Нее мы взирать не в силах, / и почесть достойную невозможно Ей воздать, / (Глас 4)"},
  {"id": "ru-usp-0035", "section": "service", "who": "reader", "text": "ибо превосходство Её выше всякой мысли!» / (Глас 8)"},
  {"id": "ru-usp-0036", "section": "service", "who": "reader", "text": "Потому, пречистая Богородица, / всегда живя с живоносным Царем и Сыном Твоим, / ходатайствуй непрестанно о сохранении и спасении / от всякого нападения вражеского / нового народа Твоего; / ибо мы покровительство Твое обрели, / (Глас 1)"},
  {"id": "ru-usp-0037", "section": "service", "who": "reader", "text": "и во веки Тебя блистательно прославляем!"},
  {"id": "ru-usp-0038", "section": "service", "who": "rubric", "text": "Вход. Прокимен дня, и три чтения праздника:"},
  {"id": "ru-usp-0039", "section": "service", "who": "reader", "text": "1. Бытия чтение"},
  {"id": "ru-usp-0040", "section": "service", "who": "reader", "text": "Отправился Иаков от Колодца Клятвы и пошел в Харран, и пришел на одно место, и лег там спать, потому что зашло солнце. И взял один из камней того места, и положил под голову себе, и уснул на том месте. И увидел во сне: и вот, лестница утверждена на земле, а ее верх доходит до неба; и Ангелы Божии восходили и нисходили по ней. Господь же стоял на ней, и сказал Он: «Я – Бог Авраама, отца твоего, и Бог Исаака; не бойся. Землю, на которой ты спишь, тебе Я дам ее и семени твоему; и будет семя твоё, как песок земной; и распространится к морю, и к югу, и к северу, и к востоку; и благословятся в тебе и в семени твоем все племена земные; и вот, Я с тобою, сохраняя тебя на всяком пути, куда бы ты ни пошел; и возвращу тебя в землю сию, ибо не оставлю тебя, доколе не совершу Я того, что сказал тебе». И пробудился Иаков от сна своего и сказал: «Господь присутствует на месте этом; а я не знал!» И убоялся и сказал: «Как страшно место сие! Это не что иное, как дом Божий, и это – врата небесные!» Быт 28:10–17"},
  {"id": "ru-usp-0041", "section": "service", "who": "reader", "text": "2. Пророчества Иезекииля чтение"},
  {"id": "ru-usp-0042", "section": "service", "who": "reader", "text": "[Так говорит Господь:] со дня восьмого и далее будут приносить священники на жертвеннике всесожжения ваши и жертвы о спасении вашем; и Я благосклонно приму вас, говорит Господь. И возвратил он меня на путь ко внешним вратам святилища, обращенным на восток, и они были затворены. И сказал мне Господь: «Врата эти будут затворены, и не отворятся, и никто не пройдет через них, ибо Господь, Бог Израилев, пройдет через них, и они будут затворены. Потому правитель – он сядет в них, чтобы вкусить хлеб пред Господом; войдет путем притвора этих ворот, и тем же путем выйдет». И ввел меня по пути к воротам святилища, тем, что к северу напротив храма, и я увидел: и вот, полон славы дом Господень. Иез 43:27; 44:1–4"},
  {"id": "ru-usp-0043", "section": "service", "who": "reader", "text": "3. Притчей чтение"},
  {"id": "ru-usp-0044", "section": "service", "who": "reader", "text": "Премудрость построила себе дом, утвердила семь столбов, заколола свои жертвы и растворила в чаше своей вино и приготовила свою трапезу; послала своих рабов, созывая с возвышенною проповедью к чаше: «Кто неразумен, пусть повернет ко мне!» И скудоумным она сказала: «Придите, вкусите хлебы мои и испейте вина, которое я растворила вам; оставьте неразумие, и живы будете, и взыщите разума, чтобы пожить и достичь рассудительности в познании». Поучающий злых наживет себе бесславие, а обличающий нечестивого – опозорит себя. Не обличай злых, чтобы они не возненавидели тебя; обличай мудрого, и он возлюбит тебя; давай повод мудрому, и он будет еще мудрее; сообщай праведному, и он приложит внимание. Начало премудрости – страх Господень, и совет святых – разум; познать же Закон – свойство ума доброго: ведь таким образом проживешь ты долгое время и прибавится тебе лет жизни. Притч 9:1–11"},
  {"id": "ru-usp-0045", "section": "service", "who": "reader", "text": "Стихиры на литии самогласные, глас 1"},
  {"id": "ru-usp-0046", "section": "service", "who": "reader", "text": "Надлежало очевидцам Слова и служителям / и успение Матери Его по плоти видеть, / ибо оно было последним совершившимся над Нею таинством; / так чтобы они не только восхождение от земли Спасителя узрели, / но и о преставлении Родившей Его свидетельствовали. / Потому, отовсюду перенесенные Божественною силою, / они прибыли в Сион / и провожали идущую на небо Высшую Херувимов. / Ей и мы с ними поклоняемся, / как ходатайствующей о душах наших."},
  {"id": "ru-usp-0047", "section": "service", "who": "reader", "text": "Анатолия, глас 2"},
  {"id": "ru-usp-0048", "section": "service", "who": "reader", "text": "Небес высшая, и Херувимов славнейшая, / и честью все творение превосходящая, / Ставшая за величайшую чистоту / вечного Существа обителью, / в сей день в руки Сына предает всесвятую душу, / и с Нею все исполняется радости, / и нам даруется великая милость."},
  {"id": "ru-usp-0049", "section": "service", "who": "reader", "text": "Преп. Иоанна Дамаскина, глас тот же"},
  {"id": "ru-usp-0050", "section": "service", "who": "reader", "text": "Всенепорочная Невеста / и Матерь Благоволения Отца, / предназначенная стать собственным жилищем Богу / при Его неслиянном с природой человеческой соединении, / в сей день пречистую душу Творцу и Богу предает, / которую с достойной Бога честью принимают Бесплотных Силы, / и к жизни переселяется истинная Матерь Жизни, / светильник неприступного Света, / спасение верных и надежда душ наших."},
  {"id": "ru-usp-0051", "section": "service", "who": "reader", "text": "Патриарха Германа, глас 3"},
  {"id": "ru-usp-0052", "section": "service", "who": "reader", "text": "Придите, все пределы земли, / священное преставление Богоматери восхвалим, / ибо в руки Сына Она непорочную душу отдала; / потому святым успением Её мир оживотворился, / псалмами, и гимнами, и песнями духовными / с бесплотными и Апостолами празднуя светло!"},
  {"id": "ru-usp-0053", "section": "service", "who": "reader", "text": "Слава, глас 5, Феофана Начертанного, епископа Никейского"},
  {"id": "ru-usp-0054", "section": "service", "who": "reader", "text": "Придите, собрание любителей праздников, / придите, и составим хор, / придите увенчаем песнопениями Церковь / при упокоении Ковчега Божия; / ибо в сей день небо объятия простирает, / принимая Родившую всем миром Невместимого, / и земля, отдавая Источник Жизни, / украшается благословением и благолепием. / Ангелы составляют хор с Апостолами, / с трепетом взирая на Переселяемую из жизни в жизнь, / Начальника жизни Родившую. / Все поклонимся Ей, молясь: / «Не забудь, Владычица, ближайшего родства / с нами, празднующими с верою / всесвятое Твое успение!»"},
  {"id": "ru-usp-0055", "section": "service", "who": "reader", "text": "И ныне, глас тот же: Воспойте, люди, Матери Бога нашего, воспойте, / ибо Она в сей день предает всесветлую душу Свою / в пречистые руки от Нее без семени Воплотившегося, / Которого и молит непрестанно / даровать вселенной мир / и великую милость."},
  {"id": "ru-usp-0056", "section": "service", "who": "reader", "text": "Стихиры на стиховне самогласные, глас 4"},
  {"id": "ru-usp-0057", "section": "service", "who": "reader", "text": "Придите, воспоем, люди, / всесвятую Деву чистую, / из Которой неизреченно прошло / воплотившееся Слово Отчее, / воспоем, восклицая и возглашая: / «Благословенна Ты между женами; / блаженно чрево, вместившее Христа!» / В Его святые руки душу предав, / ходатайствуй, Пречистая, / о спасении душ наших. Стих:"},
  {"id": "ru-usp-0058", "section": "service", "who": "reader", "text": "Встань, Господи, на место покоя Твоего, / Ты и ковчег святыни Твоей. Пс 131:8"},
  {"id": "ru-usp-0059", "section": "service", "who": "reader", "text": "В сей день Давидову песнь / воспоем, люди, Христу Богу: / «Приведутся, сказал он, Царю девы вслед за Ней, / приведутся в веселии и радости». / Ибо Та, Которая от семени Давидова, / благодаря Которой мы обожены, / руками Своего Сына и Владыки / славно и выше слова переселяется. / Воспевая Её, как Матерь Божию, / мы восклицаем и возглашаем: / «Спаси нас, исповедующих Тебя Богородицею, от всякой превратности / и избавь от бед души наши!» Стих:"},
  {"id": "ru-usp-0060", "section": "service", "who": "reader", "text": "Клялся Господь Давиду в истине / и не отречется от нее. Пс 131:11А"},
  {"id": "ru-usp-0061", "section": "service", "who": "reader", "text": "Всесвященное Твое успение, / всесвятая Дева чистая, / множества Ангелов на небесах / и мы, род человеческий, на земле прославляем, / ибо Ты стала Матерью Творца всего, Христа Бога. / Не прекращай, просим, молить Его за нас, / на Тебя после Бога надежды возложивших, / Богородица всехвальная и брака не познавшая!"},
  {"id": "ru-usp-0062", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тот же: Когда отошла Ты, Богородица Дева, / к Родившемуся от Тебя неизреченно / присутствовал там Иаков, брат Божий и первый иерарх, / а также Петр, почетнейший глава, вершина богословов; / и весь божественный Апостолов сонм, / яснейшим образом богословствовал, / воспевая божественное и страшное таинство / домостроительства Христа Бога. / И, предав погребению Твое живоначальное и Бога принявшее тело, / они радовались, Всехвальная; / а свыше всесвятые и главнейшие Ангельские Силы, поражаясь чуду, / склонясь, друг другу возглашали: / «Поднимите врата ваши и примите / Родившую неба и земли Творца; / воспоем же славословиями священное и святое тело, / вместившее для нас Невидимого и Господа нашего!» / Потому и мы, память Твою празднуя, / взываем Тебе, всехвальная: / «Возвысь рог христиан / и спаси души наши!»"},
  {"id": "ru-usp-0063", "section": "service", "who": "reader", "text": "Тропарь, глас 1"},
  {"id": "ru-usp-0064", "section": "service", "who": "reader", "text": "При рождении Христа Ты девство сохранила / и по смерти мира не оставила, Богородица: / к жизни Ты перешла, как Матерь Жизни, / и молитвами Твоими избавляешь от смерти души наши. (3)"},
  {"id": "ru-usp-0065", "section": "service", "who": "rubric", "text": "Успение пресвятой славной владычицы нашей богородицы и приснодевы марии"},
  {"id": "ru-usp-0066", "section": "service", "who": "reader", "text": "НА УТРЕНИ На"},
  {"id": "ru-usp-0067", "section": "service", "who": "reader", "text": "Бог Господь:"},
  {"id": "ru-usp-0068", "section": "service", "who": "reader", "text": "Тропарь, глас 1 При рождении Христа Ты девство сохранила / и по смерти мира не оставила, Богородица: / к жизни Ты перешла, как Матерь Жизни, / и молитвами Твоими избавляешь от смерти души наши. (3)"},
  {"id": "ru-usp-0069", "section": "service", "who": "reader", "text": "По 1 стихословии седален, глас 1 Подобен: Воины, охранявшие гроб Твой:"},
  {"id": "ru-usp-0070", "section": "service", "who": "reader", "text": "Почтеннейший сонм мудрых Апостолов, / чудесно собран был для погребения с почетом / тела Твоего пречистого, Богородица всехвальная; / с ними воспели и Ангелов множества, / благоговейно восхваляя преставление Твое, / которое мы с верою празднуем."},
  {"id": "ru-usp-0071", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-usp-0072", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-usp-0073", "section": "service", "who": "reader", "text": "По 2 стихословии седален, глас 3 Подобен: Красоте девства Твоего:"},
  {"id": "ru-usp-0074", "section": "service", "who": "reader", "text": "При рождении от Тебя Христа / зачатие было без семени, / при успении Твоем / – омертвение без тления; / чудо с чудом соединилось / в двойное чудо, Богородица. / Ибо как, мужа не познав, / питаешь Ты Младенца, оставаясь чистою? / И как Ты, Матерь Божия, / иго смерти носишь, благоухая мvром? / Потому мы с Ангелом взываем Тебе: / «Радуйся, Благодатная!»"},
  {"id": "ru-usp-0075", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-usp-0076", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-usp-0077", "section": "service", "who": "reader", "text": "Величание Величаем Тебя, / пренепорочная Матерь Христа Бога нашего, / и всеславное славим / успение Твое."},
  {"id": "ru-usp-0078", "section": "service", "who": "reader", "text": "Псалом избранный Воскликните Господу, вся земля. / Воспойте же имени Его. / Возгласите пред Царем – Господом. / Прославляйте Его, хвалите имя Его. / Во граде Господа сил, во граде Бога нашего. / Мирным пребыло место Его, и жилище Его на Сионе. / Славное сказано о тебе, город Божий. / Бог основал его навек. / Освятил обитель Свою Всевышний. / Святость и великолепие во святилище Его. / Буду петь и воспевать во славе моей. / Чашу спасения приму и имя Господне призову. / С миром лягу и сразу усну. / Возвратись, душа моя, к покою Твоему, ибо Господь облагодетельствовал тебя. / Господь праведный рассёк шеи грешников. / Встань, Господи, на место покоя Твоего, Ты и ковчег святыни Твоей. / Дому Твоему подобает святыня, Господи, на долгие дни. / Вспомнят имя Твоё во всяком роде и роде."},
  {"id": "ru-usp-0079", "section": "service", "who": "reader", "text": "Пс 65:2А; 65:2Б; 97:6Б; 99:4В; 47:9Б; 75:3; 86:3; 47:9Г; 45:5; 95:6Б; 107:2Б; 115:4; 4:9А; 114:7; 128:4; 131:8; 92:5Б; 44:18А"},
  {"id": "ru-usp-0080", "section": "service", "who": "reader", "text": "После полиелея седален, глас 4 Подобен: Поражен был Иосиф:"},
  {"id": "ru-usp-0081", "section": "service", "who": "reader", "text": "Возгласи, Давид, что ныне за праздник? / – Он в честь Той, Которую воспел я, говорит он, в Книге Псалмов, / как Дочь – Отроковицу Божию и Деву: / Её перенес к тамошним обителям / Христос, без семени от Нее рожденный. / И потому радуются матери и дочери, / и невесты Христовы, взывая: / «Радуйся, Переселившаяся к вышнему Царству!»"},
  {"id": "ru-usp-0082", "section": "service", "who": "reader", "text": "Слава, и ныне:"},
  {"id": "ru-usp-0083", "section": "service", "who": "rubric", "text": "повторяем то же."},
  {"id": "ru-usp-0084", "section": "service", "who": "rubric", "text": "Степенна, 1-й антифон 4-го гласа."},
  {"id": "ru-usp-0085", "section": "service", "who": "reader", "text": "Прокимен, глас 4 Вспомнят имя Твоё / во всяком роде и роде. Стих:"},
  {"id": "ru-usp-0086", "section": "service", "who": "reader", "text": "Услышь, Дочь, и посмотри, и склони ухо Твоё. Пс 44:18А, 11А"},
  {"id": "ru-usp-0087", "section": "service", "who": "reader", "text": "Евангелие от Луки, зачало 4"},
  {"id": "ru-usp-0088", "section": "service", "who": "reader", "text": "В те дни Мариам, встав, пошла с поспешностью в горную страну, в город Иудин, и вошла в дом Захарии и приветствовала Елисавету. И было: когда услышала Елисавета приветствие Марии, взыграл младенец во чреве ее; и исполнилась Духа Святого Елисавета, и воскликнула громким голосом, и сказала: «Благословенна Ты между женами, и благословен Плод чрева Твоего! И откуда это мне, что пришла Матерь Господа моего ко мне? Ибо вот, когда прозвучал глас приветствия Твоего в ушах моих, взыграл младенец от радости во чреве моем, и блаженна Уверовавшая, что совершится сказанное Ей от Господа». И сказала Мариам: «Величает душа Моя Господа, и возрадовался дух Мой о Боге, Спасителе Моем, что призрел Он на смирение рабы Своей; ибо вот, отныне будут называть Меня блаженной все роды; что сотворил Мне великое Сильный, и свято имя Его». Пробыла же Мариам с нею около трех месяцев и возвратилась в дом Свой. Лк 1:39–49, 56"},
  {"id": "ru-usp-0089", "section": "service", "who": "reader", "text": "После 50 псалма стихира, глас 6"},
  {"id": "ru-usp-0090", "section": "service", "who": "reader", "text": "Когда подготовлялось пречистого Твоего тела перенесение, / тогда Апостолы, окружая одр, / с трепетом на Тебя взирали, / и одни вглядываясь в тело, / изумлением были охвачены, / а Петр со слезами взывал Тебе: / «О Дева, явственно вижу Тебя простертой навзничь, / Жизнь всех, и поражаюсь / Той, в Которую вселилась жизни будущей Услада!» / Но, о Пречистая, моли усердно Сына Твоего и Бога / о сохранении стада Твоего невредимым."},
  {"id": "ru-usp-0091", "section": "service", "who": "rubric", "text": "Каноны. Первый – св. Космы Маиумского, глас 1, и второй – св. Иоанна Дамаскина, глас 4; ирмосы обоих канонов исполняются дважды, тропари все поем на 12. Катавасия: каждый хор исполняет свой ирмос."},
  {"id": "ru-usp-0092", "section": "service", "who": "reader", "text": "Песнь 1"},
  {"id": "ru-usp-0093", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0094", "section": "service", "who": "reader", "text": "Изукрашенная Божественною славою / священная и славная, Дева, память Твоя, / собрала всех верных к веселию, / чтобы под началом Мариам с хороводами и тимпанами / воспевать Твоему Единородному, / ибо славно Он прославился."},
  {"id": "ru-usp-0095", "section": "service", "who": "reader", "text": "Полк невещественных небожителей / окружал на Сионе божественное тело Твое; / а множество Апостолов, / внезапно от пределов земли собравшись, / вдруг предстало Тебе, Богородица; / с ними и мы, Чистая, / Твою священную память славим."},
  {"id": "ru-usp-0096", "section": "service", "who": "reader", "text": "Почести победы над природою / Ты стяжала, Чистая, носив во чреве Бога; / но все же, подражая Творцу Своему и Сыну, / Ты сверхъестественно подчиняешься законам естества; / потому, и умирая, восстаешь / для вечной жизни с Сыном."},
  {"id": "ru-usp-0097", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0098", "section": "service", "who": "reader", "text": "Отверзу уста мои, / и они исполнятся Духа, / и слово изреку Царице Матери, / и явлюсь светло торжествующим, / и воспою радостно Ее успение."},
  {"id": "ru-usp-0099", "section": "service", "who": "reader", "text": "Девы отроковицы, / с Мариам пророчицею / песнь надгробную ныне возгласите, / ибо Дева и единственная Богородица / в Свой небесный удел переходит."},
  {"id": "ru-usp-0100", "section": "service", "who": "reader", "text": "По достоинству Тебя, Пречистая, / как небо одушевленное, / приняли небесные божественные обители, / и, светло украшенная, как невеста всенепорочная, / Ты предстала Царю и Богу."},
  {"id": "ru-usp-0101", "section": "service", "who": "reader", "text": "Песнь 3"},
  {"id": "ru-usp-0102", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0103", "section": "service", "who": "reader", "text": "Творческая и объемлющая все / Божия Мудрость и Сила, / твердой и непоколебимой утверди Церковь, Христе, / ибо Ты один свят, / во святых почивающий."},
  {"id": "ru-usp-0104", "section": "service", "who": "reader", "text": "Как женщину смертную, / но и сверхъестественно – Матерь Божию, / зная Тебя, Всенепорочная, славные Апостолы / трепетными руками касались Тебя, блистающей славою, / взирая на Тебя, как на принявшую Бога скинию."},
  {"id": "ru-usp-0105", "section": "service", "who": "reader", "text": "Настигло наглые руки дерзкого, / отсечению подвергнув их, / правосудие Бога, оградившего / ради славы Божества / честь Одушевленного Ковчега, / в котором Слово сделалось плотию."},
  {"id": "ru-usp-0106", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0107", "section": "service", "who": "reader", "text": "Твоих песнопевцев, Богородица, / живой и обильный источник, / устроивших духовный праздник, утверди / и в божественной памяти Твоей / удостой венцов славы."},
  {"id": "ru-usp-0108", "section": "service", "who": "reader", "text": "Произойдя, Чистая, из смертных чресл, / Ты пришла к кончине, природе сообразной; / но родив действительную Жизнь, / переселилась к Жизни божественной и ипостасной."},
  {"id": "ru-usp-0109", "section": "service", "who": "reader", "text": "Сонм богословов от пределов земли, / а свыше – Ангелов множество / к Сиону спешили по мановению всесильному, / чтобы достойным образом послужить / при погребении Твоем, Владычица."},
  {"id": "ru-usp-0110", "section": "service", "who": "reader", "text": "Ипакои, глас 8 Блаженною именуем Тебя / мы, все роды, Богородица Дева, / ибо беспредельный Бог наш, Христос, / в Тебе вместиться благоволил. / Блаженны и мы, имея в Тебе защиту, / ибо Ты день и ночь ходатайствуешь о нас, / и скипетры царства Твоими мольбами укрепляются. / Потому, воспевая, взываем Тебе: / «Радуйся, Благодатная, Господь с Тобою!»"},
  {"id": "ru-usp-0111", "section": "service", "who": "reader", "text": "Песнь 4"},
  {"id": "ru-usp-0112", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0113", "section": "service", "who": "reader", "text": "Изречения и загадки пророков / приоткрыли воплощение Твое от Девы, Христе: / «Сияние молнии Твоей / для просвещения язычников выйдет, / и возгласит Тебе бездна с веселием: / Силе Твоей слава, Человеколюбец!»"},
  {"id": "ru-usp-0114", "section": "service", "who": "reader", "text": "Посмотрите, народы, и удивитесь, / ибо святая и славнейшая Гора Божия / превыше холмов небесных поднимается; / Небо Земное поселяемо бывает / на земле нетленной и небесной."},
  {"id": "ru-usp-0115", "section": "service", "who": "reader", "text": "К жизни вечной и лучшей переходом / стала смерть Твоя, Чистая, / перенося Тебя, Непорочная, от жизни временной / к поистине божественной и неизменной, / чтобы в радости созерцать Тебе / Сына Твоего и Господа."},
  {"id": "ru-usp-0116", "section": "service", "who": "reader", "text": "Поднялись врата небесные, / и Ангелы воспели, / и принял Христос сокровище / девства Матери Своей; / Херувимы преклонились пред Тобой с веселием, / Серафимы же Тебя славят, радуясь."},
  {"id": "ru-usp-0117", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0118", "section": "service", "who": "reader", "text": "Созерцая неисследимый Божий совет / о Твоем, Всевышний, воплощении от Девы, / пророк Аввакум восклицал: / «Слава силе Твоей, Господи!»"},
  {"id": "ru-usp-0119", "section": "service", "who": "reader", "text": "Дивно было видеть / одушевленное Небо всех Царя / недра земные проходящим. / Как чудны дела Твои! / Слава силе Твоей, Господи!"},
  {"id": "ru-usp-0120", "section": "service", "who": "reader", "text": "Если и непостижимый Плод Её, / Тот, через Кого возникло небо, / добровольно принял погребение, как смертный, / то как избегла бы погребения / безбрачно Родившая?"},
  {"id": "ru-usp-0121", "section": "service", "who": "reader", "text": "При Твоем преставлении, Матерь Божия, / Ангельские воинства со страхом и радостью / покрывали священнейшими крылами / пространнейшее и вместившее Бога тело Твое."},
  {"id": "ru-usp-0122", "section": "service", "who": "reader", "text": "Песнь 5"},
  {"id": "ru-usp-0123", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0124", "section": "service", "who": "reader", "text": "Божественную и неизреченную красоту / совершенств Твоих, Христе, поведаю; / ибо Ты, воссиявший от вечной славы / как столь же вечное и ипостасное сияние, / воплотившись от девственного чрева, взошел как солнце / находящимся во тьме и тени."},
  {"id": "ru-usp-0125", "section": "service", "who": "reader", "text": "Сонм Апостолов, носимый как бы на облаке, / от пределов земли собираем был к Сиону / послужить Тебе, Дева, легкому облаку, / из которого Всевышний Бог взошел, как солнце правды, / находящимся во тьме и тени."},
  {"id": "ru-usp-0126", "section": "service", "who": "reader", "text": "Звучнее труб боговдохновенные языки / богословствующих мужей к Богородице взывали, / песнь надгробную возглашая Духом: / «Радуйся, нетленный Источник / живоначального и спасительного для всех / Божия воплощения!»"},
  {"id": "ru-usp-0127", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0128", "section": "service", "who": "reader", "text": "Изумился весь мир / о священном успении Твоем: / ибо Ты, брака не познавшая Дева, / от земли переселилась в вечные обители / и к бесконечной жизни, / всем, воспевающим Тебя, / спасение подавая."},
  {"id": "ru-usp-0129", "section": "service", "who": "reader", "text": "Трубы богословов да гремят в сей день, / а многоречивый язык людей / ныне да возвещает хвалы; / да оглашается воздух, сияя безмерным светом, / Ангелы да воспевают / пречистой Девы успение."},
  {"id": "ru-usp-0130", "section": "service", "who": "reader", "text": "Подобало Тебе, сосуду избранному, Дева, / песнопениями в Твою честь при Твоем исходе во всем изумлять, / всей быть освященной для Бога, / для всех – боговдохновенной, / такой и быть поистине и являться, / Богородица всепрославленная."},
  {"id": "ru-usp-0131", "section": "service", "who": "reader", "text": "Песнь 6"},
  {"id": "ru-usp-0132", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0133", "section": "service", "who": "reader", "text": "Морской огонь внутри рожденного в пучине кита / был тридневного Твоего погребения прообразом, / толкователем которого Иона является, / ибо, сохраненный невредимым, / каким и был до поглощения, он взывал: / «Принесу Тебе жертву с гласом хвалебным, Господи!»"},
  {"id": "ru-usp-0134", "section": "service", "who": "reader", "text": "Являет на Тебе сверхъестественное / Царь всего, Бог, / ибо как Он Тебя при родах Девою сохранил, / так и во гробе тело соблюл нетленным / и вместе – прославил божественным переселением, / честь Тебе, как Сын Матери, воздавая."},
  {"id": "ru-usp-0135", "section": "service", "who": "reader", "text": "Тебя, Дева, как поистине светлый / светильник невещественного Огня, / кадильницу златую божественного Угля, / сосуд с манной и жезл, / скрижаль, Богом писанную, / ковчег святой, трапезу Хлеба жизни, / поселило во Святом Святых Дитя Твое."},
  {"id": "ru-usp-0136", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0137", "section": "service", "who": "reader", "text": "Божественный сей и всеми чтимый / совершая праздник Богоматери, / придите, богомудрые, начнем рукоплескать, / от Нее рожденного Бога славя."},
  {"id": "ru-usp-0138", "section": "service", "who": "reader", "text": "Из Тебя воссияла Жизнь, / ключей девства не нарушив. / Как же пречистое и живоначальное тело Твое / испытанию смертью сделалось причастным?"},
  {"id": "ru-usp-0139", "section": "service", "who": "reader", "text": "Став храмом Жизни, / вечной жизни Ты достигла, / ибо чрез смерть Ты к жизни перешла, / как родившая Жизнь ипостасную."},
  {"id": "ru-usp-0140", "section": "service", "who": "reader", "text": "Кондак, глас 2 Вмолитвах неусыпающую Богородицу / и в ходатайствах надежду непоколебимую / гроб и смертность не удержали. / Ибо Её, как Матерь Жизни, к жизни перенес / Вселившийся в Её чрево вечно девственное. Икос:"},
  {"id": "ru-usp-0141", "section": "service", "who": "reader", "text": "Огради мои помышления, Спаситель мой, / ибо я Стену мiра воспеть дерзаю, / пречистую Матерь Твою; / на башне слов дай силу мне, / и в чертогах мыслей укрепи меня, / ибо возглашаешь Ты, / что с верою просящим их прошения исполняешь; / Ты же даруй мне язык, / речь и разум безупречные, / ибо всякий дар просвещения от Тебя ниспосылается, Податель света, / вселившийся в чрево вечно девственное."},
  {"id": "ru-usp-0142", "section": "service", "who": "reader", "text": "Песнь 7"},
  {"id": "ru-usp-0143", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0144", "section": "service", "who": "reader", "text": "Божественная любовь, / бесстыдной ярости и огню сопротивляясь, / орошала огонь, / а над яростью смеялась, / боговдохновенной разумной трехструнной лирой праведных / отвечая музыкальным орудиям среди пламени: / «Препрославленный Боже отцов и наш, / благословен Ты!»"},
  {"id": "ru-usp-0145", "section": "service", "who": "reader", "text": "Богом созданные скрижали, / писанные Божественным Духом, / Моисей во гневе сокрушил; / но его Владыка, сохранив невредимой Свою Родительницу, / ныне Её в небесные обители вселил. / Торжествуя с Нею, будем взывать Христу: / «Препрославленный Боже отцов и наш, / благословен Ты!»"},
  {"id": "ru-usp-0146", "section": "service", "who": "reader", "text": "На кимвалах чистых уст / и музыкальной лирою сердца, / благозвучною трубою возвышенного размышления / в знаменательный избранный день / преставления Девы и Чистой, / рукоплеща усердными руками, будем взывать: / «Препрославленный Боже отцов и наш, / благословен Ты!»"},
  {"id": "ru-usp-0147", "section": "service", "who": "reader", "text": "Богомудрый народ собрался, / ибо обитель славы Божией / от Сиона переселяется в небесное жилище, / где чистый голос празднующих, / голос несказанной радости, / и в веселии взывающих Христу: / «Препрославленный Боже отцов и наш, / благословен Ты!»"},
  {"id": "ru-usp-0148", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0149", "section": "service", "who": "reader", "text": "Не почтили богомудрые / творения больше Творца, / но угрожавший им огонь мужественно поправ, / радостно воспевали: / «Прехвальный Господь и Бог отцов, / благословен Ты!»"},
  {"id": "ru-usp-0150", "section": "service", "who": "reader", "text": "Юноши и девы, старцы и князья, / и цари с судьями, воспойте, / почитая память Девы и Богоматери: / «Господь и Бог отцов, благословен Ты!»"},
  {"id": "ru-usp-0151", "section": "service", "who": "reader", "text": "Да вострубят трубою Духа горы небесные, / да радуются холмы, / и да торжествуют божественные Апостолы: / к Сыну переселяется Царица, / с Ним вечно владычествующая."},
  {"id": "ru-usp-0152", "section": "service", "who": "reader", "text": "Всесвященное преставление / божественной Твоей и нетленной Матери / соединило вышних Сил надмирные полки / общей радостью с земными, Тебе поющими: / «Боже, благословен Ты!»"},
  {"id": "ru-usp-0153", "section": "service", "who": "reader", "text": "Песнь 8"},
  {"id": "ru-usp-0154", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0155", "section": "service", "who": "reader", "text": "Ангел Божий всемощный / показал для отроков пламя / орошающим праведных, а нечестивых опаляющим; / Богородицу же Бог соделал живоначальным источником, / изливающим смерти разрушение и жизнь поющим: / «Единого Создателя будем петь, избавленные, / и превозносить во все века!»"},
  {"id": "ru-usp-0156", "section": "service", "who": "reader", "text": "Все множество богословов / на Сионе провожало ковчег святыни, / такими словами восклицая: / «Куда идешь Ты ныне, Скиния живого Бога? / Не перестань взирать на воспевающих с верою: / Единого Создателя будем петь, избавленные, / и превозносить во все века!»"},
  {"id": "ru-usp-0157", "section": "service", "who": "reader", "text": "Отходя и как бы руки воздев, Всенепорочная, / руки, Бога обнимавшие телесно, / Ты, как Матерь, с дерзновением сказала Рожденному: / «Тех, кого Ты вверил Мне, вовеки сохраняй, Тебе взывающих: / «Единого Создателя будем петь, избавленные, / и превозносить во все века!»"},
  {"id": "ru-usp-0158", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0159", "section": "service", "who": "reader", "text": "Отроков благочестивых в печи / Дитя Богородицы спасло: / тогда – прообразуемое, а ныне – действующее; / всю вселенную созывает Он петь Тебе. / Пойте Господа, творения, / и превозносите во все века!"},
  {"id": "ru-usp-0160", "section": "service", "who": "reader", "text": "Память Твою, Дева чистая, / славят Начальства, как и Власти с Силами, / Ангелы, Архангелы, Престолы, Господства, / Херувимы и страшные Серафимы, / и мы, род человеческий, поем / и превозносим во все века!"},
  {"id": "ru-usp-0161", "section": "service", "who": "reader", "text": "Необычайно Вселившийся, Богородица, / в чистое чрево Твое при воплощении, / Сам всесвященный дух Твой приняв, / упокоил у Себя его, как Сын, воздающий долг; / потому мы воспеваем Тебя, Деву, / и превозносим во все века."},
  {"id": "ru-usp-0162", "section": "service", "who": "reader", "text": "О, превосходящие понимание чудеса / Приснодевы и Богоматери! / Ибо Она, во гроб вселившись, / раем явила его! / Стоя пред ним сегодня, мы радостно поем: / «Воспевайте Господа, творения, / и превозносите во все века!» На 9-ой песни"},
  {"id": "ru-usp-0163", "section": "service", "who": "reader", "text": "Честью высшую Херувимов:"},
  {"id": "ru-usp-0164", "section": "service", "who": "rubric", "text": "не поем, даже в воскресенье, но поем припевы праздника:"},
  {"id": "ru-usp-0165", "section": "service", "who": "reader", "text": "Мы, все роды, прославляем Тебя, / единственную Богородицу. Или:"},
  {"id": "ru-usp-0166", "section": "service", "who": "reader", "text": "Ангелы, увидев Успение Пречистой, удивились, / как Дева восходит от земли на небо. И ирмос:"},
  {"id": "ru-usp-0167", "section": "service", "who": "reader", "text": "Побеждены законы естества:"},
  {"id": "ru-usp-0168", "section": "service", "who": "rubric", "text": "Затем второй хор поет тот же припев и ирмос. И на каждый тропарь исполняют тот же припев по одному разу."},
  {"id": "ru-usp-0169", "section": "service", "who": "reader", "text": "Песнь 9"},
  {"id": "ru-usp-0170", "section": "service", "who": "rubric", "text": "Канон 1. Ирмос:"},
  {"id": "ru-usp-0171", "section": "service", "who": "reader", "text": "Побеждены законы естества / на Тебе, Дева чистая: / при родах девство сохраняется / и с жизнью обручается смерть; / после родов – Дева и по смерти – живая, / всегда спасай, / Богородица, наследие Свое!"},
  {"id": "ru-usp-0172", "section": "service", "who": "reader", "text": "Изумлялись Ангельские силы, / созерцая на Сионе своего Владыку / принимающим на руки женскую душу; / ибо Он пречисто Родившую, / как подобало Сыну, призывал: / «Приди, Священная, / будь прославлена с Сыном и Богом!»"},
  {"id": "ru-usp-0173", "section": "service", "who": "reader", "text": "Приготовил к погребению сонм Апостолов / Бога принявшее тело Твое, / со страхом на него взирая / и громким голосом взывая: / «Отходя в небесные чертоги к Сыну, / всегда спасай, Богородица, наследие Свое!»"},
  {"id": "ru-usp-0174", "section": "service", "who": "rubric", "text": "Затем первый хор поет припев второго канона:"},
  {"id": "ru-usp-0175", "section": "service", "who": "choir", "text": "Величай, душа моя, / священное преставление с земли на небо Божией Матери. И ирмос:"},
  {"id": "ru-usp-0176", "section": "service", "who": "choir", "text": "Всякий на земле рожденный:"},
  {"id": "ru-usp-0177", "section": "service", "who": "rubric", "text": "Затем второй хор поет тот же припев и ирмос. И на каждый тропарь исполняют тот же припев по одному разу."},
  {"id": "ru-usp-0178", "section": "service", "who": "rubric", "text": "Канон 2. Ирмос:"},
  {"id": "ru-usp-0179", "section": "service", "who": "choir", "text": "Всякий, на земле рожденный, / да ликует, Духом просвещаясь, / да торжествует и бесплотных Умов естество, / почитая священное преставление Богоматери, / и да взывает: / «Радуйся, Всеблаженная, / Богородица чистая, Приснодева!"},
  {"id": "ru-usp-0180", "section": "service", "who": "choir", "text": "Придите возрадуемся на Сионе, / Божественной и тучной горе живого Бога, / взирая на Богородицу; / ибо Христос переселяет Её, как Матерь, / в гораздо лучшую и божественнейшую скинию, / во Святое Святых."},
  {"id": "ru-usp-0181", "section": "service", "who": "choir", "text": "Придите, верные, / подойдем ко гробу Богоматери / и обнимем его, прикасаясь искренне сердцами, / устами, очами, челом, / и почерпнем исцелений обильные дары / из источника неиссякаемого изливающиеся."},
  {"id": "ru-usp-0182", "section": "service", "who": "choir", "text": "Прими от нас песнь надгробную, / Матерь живого Бога, / и осени светоносною и Божественною Твоею благодатию, / подавая царю победы, Христолюбивому народу мир, / поющим прощение грехов / и душевное спасение."},
  {"id": "ru-usp-0183", "section": "service", "who": "rubric", "text": "Затем оба хора вместе поют припев первого канона и ирмос:"},
  {"id": "ru-usp-0184", "section": "service", "who": "choir", "text": "Побеждены законы естества:"},
  {"id": "ru-usp-0185", "section": "service", "who": "rubric", "text": "И второго канона припев и ирмос:"},
  {"id": "ru-usp-0186", "section": "service", "who": "choir", "text": "Всякий на земле рожденный: И поклон."},
  {"id": "ru-usp-0187", "section": "service", "who": "choir", "text": "Светилен Подобен: Небо звездами:"},
  {"id": "ru-usp-0188", "section": "service", "who": "choir", "text": "Апостолы, собранные сюда с концов земли, / в Гефсиманском селении погребите тело Мое, / и Ты, Сын и Бог Мой, / прими дух Мой! (3)"},
  {"id": "ru-usp-0189", "section": "service", "who": "choir", "text": "На «хвалите» стихиры на 4, глас 4 Подобен: Как доблестного:"},
  {"id": "ru-usp-0190", "section": "service", "who": "choir", "text": "Славному успению Твоему / небеса радуются, / радостны и Ангельские воинства, / а вся земля веселится, / песнь надгробную возглашая Тебе, / Матери над всем Владычествующего, / брака не познавшая Всесвятая Дева, / род человеческий избавившая / от прародительского осуждения! (2)"},
  {"id": "ru-usp-0191", "section": "service", "who": "choir", "text": "От пределов земли собрались / избранные из Апостолов, / по мановению власти Божественной / на погребение Твое, / и Тебя, от земли к высоте поднимающуюся созерцая, / гласом Гавриила в радости взывали Тебе: / «Радуйся, Носительница всего Божества! / Радуйся, Одна, рождением от Тебя Христа / земное с вышним соединившая!"},
  {"id": "ru-usp-0192", "section": "service", "who": "choir", "text": "Жизнь носившая во чреве, / Ты к жизни перешла бессмертной / в священном успении Твоем, / когда Тебя сопровождали копьеносцы-Ангелы, / Начальства и Силы, / Апостолы, пророки и все творение, / а Сын Твой нетленными руками / принимал непорочную душу Твою, / Дева-Матерь, Божия Невеста."},
  {"id": "ru-usp-0193", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 6: При бессмертном Твоем успении, / Богородица Матерь Жизни, / облака Апостолов на воздух поднимали / и рассеянных по миру в одном месте поставили / перед пречистым Твоим телом; / и они, погребению предав его благоговейно, / возглас Гавриила воспевая, взывали: / «Радуйся, Благодатная Дева, / Матерь брака не познавшая, Господь с Тобою!» / С ними моли Его, как Сына Твоего и Бога нашего, / о спасении душ наших."},
  {"id": "ru-usp-0194", "section": "service", "who": "rubric", "text": "Славословие великое."},
  {"id": "ru-usp-0195", "section": "service", "who": "choir", "text": "Отпуст Христос, истинный Бог наш, по молитвам пречистой Своей Матери, святых славных и всехвальных Апостолов, святых и праведных Богоотцов Иоакима и Анны и всех святых помилует и спасет нас, как благой и Человеколюбец."},
  {"id": "ru-usp-0196", "section": "service", "who": "rubric", "text": "Успение пресвятой славной владычицы нашей богородицы и приснодевы марии"},
  {"id": "ru-usp-0197", "section": "service", "who": "choir", "text": "НА ЛИТУРГИИ"},
  {"id": "ru-usp-0198", "section": "service", "who": "rubric", "text": "Поем изобразительны; блаженны: 1-го канона песнь 3-я на 4, и 2-го канона песнь 6-я на 4. Если изволит настоятель, поем антифоны праздника."},
  {"id": "ru-usp-0199", "section": "service", "who": "choir", "text": "Антифон 1 Стих 1:"},
  {"id": "ru-usp-0200", "section": "service", "who": "choir", "text": "Воскликните Господу, / вся земля. Пс 65:2А"},
  {"id": "ru-usp-0201", "section": "service", "who": "choir", "text": "По молитвам Богородицы, Спаситель, / спаси нас. Стих 2:"},
  {"id": "ru-usp-0202", "section": "service", "who": "choir", "text": "Прославляйте Его, / хвалите имя Его. Пс 99:4В"},
  {"id": "ru-usp-0203", "section": "service", "who": "choir", "text": "По молитвам Богородицы, Спаситель, / спаси нас. Стих 3:"},
  {"id": "ru-usp-0204", "section": "service", "who": "choir", "text": "Во граде Господа сил, / во граде Бога нашего. Пс 47:9Б"},
  {"id": "ru-usp-0205", "section": "service", "who": "choir", "text": "По молитвам Богородицы, Спаситель, / спаси нас. Стих 4:"},
  {"id": "ru-usp-0206", "section": "service", "who": "choir", "text": "Мирным пребыло место Его, и жилище Его на Сионе. Пс 75:3"},
  {"id": "ru-usp-0207", "section": "service", "who": "choir", "text": "По молитвам Богородицы, Спаситель, / спаси нас. Слава, и ныне: По молитвам Богородицы, Спаситель, спаси нас."},
  {"id": "ru-usp-0208", "section": "service", "who": "choir", "text": "Антифон 2 Стих 1:"},
  {"id": "ru-usp-0209", "section": "service", "who": "choir", "text": "Любит Господь врата Сиона / больше всех селений Иакова. Пс 86:2"},
  {"id": "ru-usp-0210", "section": "service", "who": "choir", "text": "Спаси нас, Сын Божий, / дивный во святых, поющих Тебе: / аллилуия. Стих 2:"},
  {"id": "ru-usp-0211", "section": "service", "who": "choir", "text": "Славное сказано о Тебе, / город Божий. Пс 86:3"},
  {"id": "ru-usp-0212", "section": "service", "who": "choir", "text": "Спаси нас, Сын Божий, / дивный во святых, поющих Тебе: аллилуия. Стих 3:"},
  {"id": "ru-usp-0213", "section": "service", "who": "choir", "text": "Бог основал / его навек. Пс 47:9Г"},
  {"id": "ru-usp-0214", "section": "service", "who": "choir", "text": "Спаси нас, Сын Божий, / дивный во святых, поющих Тебе: аллилуия. Стих 4:"},
  {"id": "ru-usp-0215", "section": "service", "who": "choir", "text": "Освятил обитель / Свою Всевышний. Пс 45:5"},
  {"id": "ru-usp-0216", "section": "service", "who": "choir", "text": "Спаси нас, Сын Божий, / дивный во святых, поющих Тебе: аллилуия."},
  {"id": "ru-usp-0217", "section": "service", "who": "choir", "text": "Слава, и ныне: Единородный Сын:"},
  {"id": "ru-usp-0218", "section": "service", "who": "choir", "text": "Антифон 3 Стих 1:"},
  {"id": "ru-usp-0219", "section": "service", "who": "choir", "text": "Готово сердце моё, Боже, / готово сердце моё. Пс 107:2А"},
  {"id": "ru-usp-0220", "section": "service", "who": "choir", "text": "Тропарь, глас 1 При рождении Христа Ты девство сохранила / и по смерти мира не оставила, Богородица: / к жизни Ты перешла, как Матерь Жизни, / и молитвами Твоими избавляешь от смерти души наши. Стих 2:"},
  {"id": "ru-usp-0221", "section": "service", "who": "choir", "text": "Что воздам я Господу за всё, / что Он воздал мне? Пс 115:3 Тропарь:"},
  {"id": "ru-usp-0222", "section": "service", "who": "choir", "text": "При рождении Христа Ты девство сохранила: Стих 3:"},
  {"id": "ru-usp-0223", "section": "service", "who": "choir", "text": "Чашу спасения приму / и имя Господне призову. Пс 115:4 Тропарь:"},
  {"id": "ru-usp-0224", "section": "service", "who": "choir", "text": "При рождении Христа Ты девство сохранила:"},
  {"id": "ru-usp-0225", "section": "service", "who": "choir", "text": "Вход Придите, поклонимся и припадем ко Христу. / Спаси нас, Сын Божий, / по молитвам Богородицы, / поющих Тебе: Аллилуия."},
  {"id": "ru-usp-0226", "section": "service", "who": "choir", "text": "Тропарь, глас 1 При рождении Христа Ты девство сохранила / и по смерти мира не оставила, Богородица: / к жизни Ты перешла, как Матерь Жизни, / и молитвами Твоими избавляешь от смерти души наши."},
  {"id": "ru-usp-0227", "section": "service", "who": "choir", "text": "Слава, и ныне:"},
  {"id": "ru-usp-0228", "section": "service", "who": "choir", "text": "Кондак, глас 2 Вмолитвах неусыпающую Богородицу / и в ходатайствах надежду непоколебимую / гроб и смертность не удержали. / Ибо Её как Матерь Жизни к жизни перенес / Вселившийся в Её чрево вечно девственное. Трисвятое."},
  {"id": "ru-usp-0229", "section": "service", "who": "choir", "text": "Прокимен, глас 3, песнь Богородицы"},
  {"id": "ru-usp-0230", "section": "service", "who": "choir", "text": "Величает душа моя Господа / и возрадовался дух мой о Боге, Спасителе моём. Стих:"},
  {"id": "ru-usp-0231", "section": "service", "who": "choir", "text": "Что призрел Он на смирение рабы Своей, ибо отныне назовут Меня блаженной все роды. Лк 1:46 – 48"},
  {"id": "ru-usp-0232", "section": "service", "who": "choir", "text": "Апостол Послание к Филиппийцам, зачало 240"},
  {"id": "ru-usp-0233", "section": "service", "who": "choir", "text": "Братья, те же мысли да будут в вас, что и во Христе Иисусе: Он, будучи во образе Божием, не считал для Себя хищением быть равным Богу, но Самого Себя умалил, приняв образ раба, быв в подобии человеческом и по виду став как человек. Он смирил Себя, быв послушным до смерти, и смерти крестной. Потому и Бог превознес Его и даровал Ему Имя, которое выше всякого имени, чтобы во имя Иисуса преклонилось всякое колено небесных, и земных, и преисподних, и всякий язык исповедал, что Господь – Иисус Христос, во славу Бога Отца. Флп 2:5–11"},
  {"id": "ru-usp-0234", "section": "service", "who": "choir", "text": "Аллилуия, глас 2 Стих:"},
  {"id": "ru-usp-0235", "section": "service", "who": "choir", "text": "Встань, Господи, на место покоя Твоего, Ты и ковчег святыни Твоей. Стих:"},
  {"id": "ru-usp-0236", "section": "service", "who": "choir", "text": "Клялся Господь Давиду в истине и не отречется от неё. Пс 131:8, 11А"},
  {"id": "ru-usp-0237", "section": "service", "who": "choir", "text": "Евангелие от Луки, зачало 54"},
  {"id": "ru-usp-0238", "section": "service", "who": "choir", "text": "В то время вошел Иисус в одно селение. И женщина некая, по имени Марфа, приняла Его в дом свой. И у нее была сестра, звавшаяся Марией, которая, сев у ног Господа, слушала слово Его. Марфа же хлопотала о большом угощении и, подойдя, сказала: «Господи, Тебе дела нет, что сестра моя одну меня оставила служить? Скажи ей, чтобы она помогла мне». В ответ же сказал ей Господь: «Марфа, Марфа, ты заботишься и суетишься о многом, а одно только нужно: Мария же благую долю избрала, которая не отнимется у нее». Было же, когда говорил Он это, некая женщина, возвысив голос из толпы, сказала Ему: «Блаженно чрево, носившее Тебя, и сосцы, что Тебя вскормили!» Он же сказал: «Поистине блаженны слышащие слово Божие и соблюдающие его!» Лк 10:38–42; 11:27–28"},
  {"id": "ru-usp-0239", "section": "service", "who": "choir", "text": "Вместо «Достойно» Ангелы, увидев Успение Пречистой, удивились, / как Дева восходит от земли на небо."},
  {"id": "ru-usp-0240", "section": "service", "who": "rubric", "text": "Ирмос, глас 1:"},
  {"id": "ru-usp-0241", "section": "service", "who": "choir", "text": "Побеждены законы естества / на Тебе, Дева чистая: / при родах девство сохраняется / и с жизнью обручается смерть; / после родов – Дева и по смерти – живая, / всегда спасай, / Богородица, наследие Свое. И до отдания."},
  {"id": "ru-usp-0242", "section": "service", "who": "choir", "text": "Причастен Чашу спасения приму и имя Господне призову. Аллилуия. (3)"},
  {"id": "ru-usp-0243", "section": "service", "who": "choir", "text": "Пс 115:4"},
  {"id": "ru-usp-0244", "section": "service", "who": "rubric", "text": "На трапезе утешение братии. Аще ли будет праздник сей в среду или в пяток, разрешаем точию на рыбу и вино. Аще ли в понедельник, и миряне разрешают на мясо, и сыры и яица. Монаси же точию на рыбу и вино. Празднуется убо сей праздник девять дней."},
];

